// resources writes the request bodies, query enums and response shapes of
// the resource methods.
func (g *gen) resources(spec, schemas *node) {
	g.requests = true
	g.shared = requestShared
	g.kinds = map[string]string{}
	g.shapes = map[string]string{}
	g.override = requestOverrides
	defer func() { g.requests = false }()

	for _, rq := range requests {
		body := operation(spec, rq.op).get("requestBody", "content", "application/json", "schema")
		if body == nil {
			log.Fatalf("genparams: %s has no JSON request body", rq.op)
		}
		g.p("// %s is what %s sends. It is checked before anything is sent.\n", rq.name, rq.method)
		if bs, _ := branches(body); len(bs) > 1 {
			g.requestUnion(rq.name, body, bs)
			continue
		}
		g.object(rq.name, body, "", "", "")
	}

	// StorageProvider: the providers Storage.Create can connect, from its branches.
	var providers []string
	bs, _ := branches(operation(spec, "POST /storage").get("requestBody", "content", "application/json", "schema"))
	for _, b := range bs {
		if _, v := enumDiscriminator(b); v != "" {
			providers = append(providers, v)
		}
	}
	g.enum("StorageProvider", synthetic("StorageProvider names where a storage connection's bucket lives.", providers), providers, false)

	for _, q := range queryEnums {
		var schema *node
		for _, p := range operation(spec, q.op).fields["parameters"].itemsOrNil() {
			if p.str("name") == q.param && p.str("in") == "query" {
				schema = p.fields["schema"]
			}
		}
		if schema == nil || !schema.has("enum") {
			log.Fatalf("genparams: %s has no enum query parameter %s", q.op, q.param)
		}
		g.enum(q.name, schema, schema.strings("enum"), false)
	}

	r := &resp{schemas: schemas, done: g.types, mapped: map[string]string{}, aliases: map[string]string{},
		fields: responseFields, renames: responseRenames, shapes: map[string]string{}}
	for _, rs := range responses {
		var parts []*node
		for _, from := range rs.from {
			parts = append(parts, responseAt(spec, schemas, from))
		}
		n := parts[0]
		if len(parts) > 1 {
			n = merge(parts)
		}
		if r.done[rs.name] {
			log.Fatalf("genparams: response type %s would be written twice", rs.name)
		}
		r.named(rs.name, n)
	}
	for _, u := range responseUnions {
		r.named(u.name, joinedUnion(spec, schemas, u.op))
	}
	g.out.Write(r.out.Bytes())
}

// requestUnion writes a body that is one of several shapes, told apart by a
// one-value property such as provider: a sealed interface and one struct per shape.
func (g *gen) requestUnion(name string, n *node, bs []*node) {
	g.claim(name)
	base := strings.TrimSuffix(name, "Params")
	var names []string
	type branch struct {
		name, disc, val string
		n               *node
	}
	var list []branch
	for _, b := range bs {
		disc, val := enumDiscriminator(b)
		if disc == "" {
			log.Fatalf("genparams: %s: a branch without a one-value discriminator", name)
		}
		bn := base + pascal(val) + "Params"
		names = append(names, bn)
		list = append(list, branch{bn, disc, val, b})
	}
	if c := comment("", n); c != "" {
		g.p("//\n%s", c)
	}
	g.p("//\n// It is one of: %s.\ntype %s interface {\n\tis%s()\n\tvalidate(c *check, path string)\n}\n\n", strings.Join(names, ", "), name, name)
	for _, b := range list {
		g.object(b.name, b.n, b.disc, b.val, "")
		g.p("func (%s) is%s() {}\n\n", b.name, name)
	}
}

// arrayChecks validates a list: required means at least one item, and each
// item gets its own checks.
func (g *gen) arrayChecks(f field, elem, ref, path string) {
	if f.required {
		g.p("\tif len(%s) == 0 {\n\t\tc.fail(%s, \"is required\")\n\t}\n", ref, path)
	}
	if lo, ok := f.schema.num("minItems"); ok && lo > 1 {
		g.p("\tif %s != nil && len(%s) < %s {\n\t\tc.fail(%s, \"must have at least %s items\")\n\t}\n", ref, ref, num(lo), path, num(lo))
	}
	if hi, ok := f.schema.num("maxItems"); ok {
		g.p("\tif len(%s) > %s {\n\t\tc.fail(%s, \"must have at most %s items\")\n\t}\n", ref, num(hi), path, num(hi))
	}
	item := fmt.Sprintf("join(%s, strconv.Itoa(i))", path)
	switch elem {
	case "enum":
		g.p("\tfor i, e := range %s {\n\t\tif !e.known() {\n\t\t\tc.fail(%s, \"is not one of the known values\")\n\t\t}\n\t}\n", ref, item)
	case "object", "union":
		g.p("\tfor i, e := range %s {\n\t\te.validate(c, %s)\n\t}\n", ref, item)
	case "string":
		if inner := g.bounds("e", "string", f.schema.fields["items"], item); inner != "" {
			g.p("\tfor i, e := range %s {\n%s\t}\n", ref, strings.ReplaceAll(inner, "\n\t", "\n\t\t"))
		} else {
			g.p("\tfor i, e := range %s {\n\t\tif e == \"\" {\n\t\t\tc.fail(%s, \"is empty\")\n\t\t}\n\t}\n", ref, item)
		}
	}
}

// joinedUnion reads the 2xx responses of op as one discriminated union: a
// response that is itself a discriminated union adds its mapping, and one that
// is a single component adds it under its one-value discriminator.
func joinedUnion(spec, schemas *node, op string) *node {
	responses := operation(spec, op).fields["responses"]
	var disc string
	var single []*node
	mapping := &node{isObj: true, fields: map[string]*node{}}
	add := func(key string, ref *node) {
		if _, ok := mapping.fields[key]; ok {
			log.Fatalf("genparams: %s: two responses are %s", op, key)
		}
		mapping.keys = append(mapping.keys, key)
		mapping.fields[key] = ref
	}
	for _, code := range responses.keys {
		if !strings.HasPrefix(code, "2") {
			continue
		}
		s := responses.get(code, "content", "application/json", "schema")
		switch {
		case s == nil:
			log.Fatalf("genparams: %s %s has no JSON response", op, code)
		case s.has("discriminator"):
			if disc = s.get("discriminator").str("propertyName"); disc == "" {
				log.Fatalf("genparams: %s %s has a discriminator without a property", op, code)
			}
			m := s.get("discriminator", "mapping")
			for _, k := range m.keys {
				add(k, m.fields[k])
			}
		case refName(s) != "":
			single = append(single, s)
		default:
			log.Fatalf("genparams: %s %s is neither a discriminated union nor a component", op, code)
		}
	}
	if disc == "" {
		log.Fatalf("genparams: %s has no discriminated response", op)
	}
	for _, s := range single {
		values := deref(schemas, s).get("properties", disc).strings("enum")
		if len(values) != 1 {
			log.Fatalf("genparams: %s: %s has no one-value %s", op, refName(s), disc)
		}
		add(values[0], &node{value: s.str("$ref")})
	}
	oneOf := &node{isArr: true}
	for _, k := range mapping.keys {
		oneOf.items = append(oneOf.items, &node{isObj: true, keys: []string{"$ref"}, fields: map[string]*node{"$ref": mapping.fields[k]}})
	}
	d := &node{isObj: true, keys: []string{"propertyName", "mapping"}, fields: map[string]*node{"propertyName": {value: disc}, "mapping": mapping}}
	return &node{isObj: true, keys: []string{"oneOf", "discriminator"}, fields: map[string]*node{"oneOf": oneOf, "discriminator": d}}
}

// operation returns the operation "METHOD /path" names.
func operation(spec *node, op string) *node {
	method, path, ok := strings.Cut(op, " ")
	if !ok {
		log.Fatalf("genparams: %q is not METHOD /path", op)
	}
	n := spec.get("paths", path, strings.ToLower(method))
	if n == nil {
		log.Fatalf("genparams: the spec has no %s", op)
	}
	return n
}

// responseAt returns the schema "METHOD /path at" or "#Component" names.
func responseAt(spec, schemas *node, from string) *node {
	if name, ok := strings.CutPrefix(from, "#"); ok {
		n := schemas.fields[name]
		if n == nil {
			log.Fatalf("genparams: no component %s", name)
		}
		return n
	}
	parts := strings.Fields(from)
	if len(parts) != 3 {
		log.Fatalf("genparams: %q is not METHOD /path at", from)
	}
	op := operation(spec, parts[0]+" "+parts[1])
	var cur *node
	for _, code := range []string{"200", "201"} {
		if s := op.get("responses", code, "content", "application/json", "schema"); s != nil {
			cur = s
			break
		}
	}
	if cur == nil {
		log.Fatalf("genparams: %s has no JSON 200 or 201 response", from)
	}
	for _, seg := range strings.Split(parts[2], ".") {
		items, maps := strings.HasSuffix(seg, "[]"), strings.HasSuffix(seg, "{}")
		seg = strings.TrimSuffix(strings.TrimSuffix(seg, "[]"), "{}")
		cur = deref(schemas, cur).get("properties", seg)
		switch {
		case cur == nil:
		case items:
			cur = deref(schemas, cur).fields["items"]
		case maps:
			cur = deref(schemas, cur).fields["additionalProperties"]
		}
		if cur == nil {
			log.Fatalf("genparams: %s: nothing at %s", from, seg)
		}
	}
	return deref(schemas, cur)
}

func deref(schemas, n *node) *node {
	if ref := refName(n); ref != "" {
		return schemas.fields[ref]
	}
	return n
}

// merge reads the fields of several objects as one: every property in order
// of first appearance, required only where every object requires it.
func merge(parts []*node) *node {
	props := &node{isObj: true, fields: map[string]*node{}}
	count := map[string]int{}
	for _, p := range parts {
		pp := p.fields["properties"]
		if pp == nil {
			log.Fatal("genparams: merging an object without properties")
		}
		for _, k := range pp.keys {
			if _, ok := props.fields[k]; !ok {
				props.keys = append(props.keys, k)
				props.fields[k] = pp.fields[k]
			}
		}
		for _, k := range p.strings("required") {
			count[k]++
		}
	}
	req := &node{isArr: true}
	for _, k := range props.keys {
		if count[k] == len(parts) {
			req.items = append(req.items, &node{value: k})
		}
	}
	out := &node{isObj: true, fields: map[string]*node{"type": {value: "object"}, "properties": props, "required": req}}
	out.keys = []string{"type", "properties", "required"}
	if d := parts[0].fields["description"]; d != nil {
		out.keys = append(out.keys, "description")
		out.fields["description"] = d
	}
	return out
}

// synthetic is a string enum schema with a description, for a set the spec
// spreads over several places.
func synthetic(desc string, values []string) *node {
	enum := &node{isArr: true}
	for _, v := range values {
		enum.items = append(enum.items, &node{value: v})
	}
	return &node{isObj: true, keys: []string{"type", "description", "enum"}, fields: map[string]*node{
		"type": {value: "string"}, "description": {value: desc}, "enum": enum,
	}}
}

// canon renders a schema without its prose, so two objects with the same
// fields and types compare equal.
func canon(n *node) string {
	if n == nil {
		return "null"
	}
	var b strings.Builder
	switch {
	case n.isObj:
		keys := append([]string(nil), n.keys...)
		sort.Strings(keys)
		b.WriteString("{")
		for _, k := range keys {
			if k == "description" || k == "example" || k == "examples" || k == "title" {
				continue
			}
			b.WriteString(strconv.Quote(k) + ":" + canon(n.fields[k]) + ",")
		}
		b.WriteString("}")
	case n.isArr:
		b.WriteString("[")
		for _, it := range n.items {
			b.WriteString(canon(it) + ",")
		}
		b.WriteString("]")
	default:
		fmt.Fprintf(&b, "%#v", n.value)
	}
	return b.String()
}
